    const tasks = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`).then(r => r.json());
    const filter = document.querySelector('#task-filter').value;
    const visible = tasks.filter(task => filter === 'All' || (filter === 'Completed') === Boolean(task.completed));
    document.querySelector('#tasks').innerHTML = visible.map(task => `<div class="task-row" data-testid="task-row"><label><input type="checkbox" aria-label="Complete ${escapeHTML(task.title)}" data-task-id="${escapeHTML(task.id)}" ${task.completed ? 'checked' : ''}>${escapeHTML(task.title)}</label></div>`).join('');
    document.querySelectorAll('#tasks input').forEach(box => box.addEventListener('change', async () => {
      await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${encodeURIComponent(box.dataset.taskId)}`, { method: 'PATCH', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ completed: box.checked }) });
      await loadTasks();
    }));
  }
  document.querySelector('#task-form').addEventListener('submit', async event => {
    event.preventDefault();
    const input = event.currentTarget.elements.title;
    const title = input.value.trim();
    if (!title) { alert.textContent = 'Task title is required'; alert.hidden = false; return; }
    const result = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ title }) });
    if (!result.ok) { alert.textContent = 'Task title is required'; alert.hidden = false; return; }
    input.value = ''; alert.hidden = true; await loadTasks();
  });
  document.querySelector('#task-filter').addEventListener('change', loadTasks);
  await loadTasks();
}
document.querySelector('.back').addEventListener('click', () => { location.href = '/'; });

